/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
 * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
 *
 * <p>By default, the layout within the configured store folder will look like:</p>
 * <pre><code>
 * storeFolder
 *   |-- stored.rules (the index file of all stored rules)
 *   |-- 6fc2fd04-b3ab-44e0-8f78-215c66f2174a (a rule violation file named randomly by UUID and referenced from stored.rules)
 *   |-- ... (more rule violation files for every rule that has been stored so far)
 * </code></pre>
 *
 * <p>The store can be configured through the following properties:</p>
 * <pre><code>
 * default.path=...               # string: the path of the folder where violation files will be stored
 * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
 * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
 * default.fileNames=random       # random, description, or a RuleViolationFileNameStrategy class name
 * default.integrity=ignore       # repair, fail, or ignore
 * </code></pre>
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String FILE_NAMES_DEFAULT = "random";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";

    private static final Pattern DESCRIPTION_WORD = Pattern.compile("[A-Za-z0-9]{4,120}");
    private static final Pattern ONLY_LINE_BREAKS = Pattern.compile("(?:\\r\\n|\\r|\\n)*");
    private static final ConcurrentHashMap<String, Object> STORE_LOCKS = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;
    private final boolean hasConstructorStrategy;
    private volatile StoreContext context;

    /**
     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = null;
        hasConstructorStrategy = false;
    }

    /**
     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        checkArgument(ruleViolationFileNameStrategy != null, "Rule violation file name strategy must not be null");
        constructorStrategy = ruleViolationFileNameStrategy;
        hasConstructorStrategy = true;
    }

    @Override
    public void initialize(Properties properties) {
        StoreConfiguration configuration = StoreConfiguration.from(properties, hasConstructorStrategy, constructorStrategy);
        Path configuredFolder = Paths.get(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT))
                .toAbsolutePath().normalize();
        String lockKey = canonicalPath(configuredFolder);
        Object lock = STORE_LOCKS.computeIfAbsent(lockKey, ignored -> new Object());

        synchronized (lock) {
            Path folder = prepareFolder(configuredFolder, configuration.storeCreationAllowed);
            Path index = folder.resolve(STORED_RULES_FILE_NAME);
            boolean indexExists = Files.exists(index, LinkOption.NOFOLLOW_LINKS);

            if (!indexExists && !configuration.storeCreationAllowed) {
                throw new StoreInitializationFailedException(String.format(
                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
            }
            if (indexExists && !isRegularFile(index)) {
                throw new StoreInitializationFailedException(String.format(
                        "The store index %s must be a regular file directly in the store folder",
                        index.toAbsolutePath()));
            }

            Properties storedRules = indexExists ? loadProperties(index) : new Properties();
            IntegrityReport report = null;
            if (configuration.integrity != Integrity.IGNORE) {
                report = inspect(folder, index, storedRules, configuration.fileNameStrategy);
                if (configuration.integrity == Integrity.FAIL && report.hasProblems()) {
                    throw new StoreInitializationFailedException(report.message());
                }
                if (configuration.integrity == Integrity.REPAIR) {
                    repair(folder, index, storedRules, report);
                }
            }

            if (!indexExists) {
                // In fail mode this point is reached only after an empty folder has been verified.
                writeProperties(index, storedRules);
            }
            context = new StoreContext(folder, index, lock, configuration.fileNameStrategy, storedRules,
                    configuration.storeUpdateAllowed);
            log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(), index.toAbsolutePath());
        }
    }

    private static Path prepareFolder(Path configuredFolder, boolean creationAllowed) {
        try {
            if (Files.exists(configuredFolder, LinkOption.NOFOLLOW_LINKS)) {
                if (!Files.isDirectory(configuredFolder)) {
                    throw new StoreInitializationFailedException(String.format(
                            "The violation store path %s is not a directory", configuredFolder));
                }
            } else {
                if (!creationAllowed) {
                    // The missing index error is more useful and is emitted by initialize().
                    return configuredFolder.toAbsolutePath().normalize();
                }
                Files.createDirectories(configuredFolder);
            }
            return configuredFolder.toRealPath();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private static String canonicalPath(Path path) {
        try {
            return path.toFile().getCanonicalPath();
        } catch (IOException e) {
            return path.toAbsolutePath().normalize().toString();
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        StoreContext current = requireContext();
        synchronized (current.lock) {
            current.storedRules = loadProperties(current.index);
            return current.storedRules.containsKey(normalize(rule.getDescription()));
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        StoreContext current = requireContext();
        String description = normalize(rule.getDescription());
        log.trace("Storing evaluated rule '{}' with {} violations: {}", description, violations.size(), violations);

        synchronized (current.lock) {
            if (!current.storeUpdateAllowed) {
                throw new StoreUpdateFailedException(String.format(
                        "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
            }

            current.storedRules = loadProperties(current.index);
            String recordedName = current.storedRules.getProperty(description);
            if (violations.isEmpty() && recordedName == null) {
                // In particular, do not ask a strategy for a name when there is nothing to store.
                return;
            }
            if (violations.isEmpty()) {
                forgetRule(current, description, recordedName);
            } else {
                storeViolations(current, description, recordedName, violations);
            }
        }
    }

    private void storeViolations(StoreContext current, String description, String recordedName, List<String> violations) {
        boolean newEntry = recordedName == null;
        String fileName = newEntry ? createFileName(current.fileNameStrategy, description) : recordedName;
        Path target = writableTarget(current, fileName, newEntry ? null : description, newEntry);
        byte[] content = serialize(violations);

        boolean existed = Files.exists(target, LinkOption.NOFOLLOW_LINKS);
        byte[] oldContent = null;
        try {
            if (existed) {
                oldContent = Files.readAllBytes(target);
                Files.write(target, content);
            } else {
                writeNewFile(target, content);
            }

            if (newEntry) {
                Properties updated = copyOf(current.storedRules);
                updated.setProperty(description, fileName);
                try {
                    writeProperties(current.index, updated);
                } catch (RuntimeException e) {
                    removeFileIfPresent(target);
                    throw e;
                }
                current.storedRules = updated;
                current.storedRules = updated;
            }
        } catch (IOException e) {
            if (existed && oldContent != null) {
                try {
                    Files.write(target, oldContent);
                } catch (IOException ignored) {
                    // The original failure is the useful one for the caller.
                }
            } else if (!existed) {
                removeFileIfPresent(target);
            }
            throw new StoreUpdateFailedException(e);
        }
    }

    private void forgetRule(StoreContext current, String description, String recordedName) {
        IntegrityReport report = inspect(current.folder, current.index, current.storedRules, current.fileNameStrategy);
        Entry entry = report.entryFor(description);
        if (entry == null) {
            return;
        }
        if (entry.valid && !entry.shared) {
            try {
                Files.deleteIfExists(entry.target);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        } else if (entry.valid && entry.shared) {
            // The other entry owns the shared file.
        } else if (entry.lexicalPath != null && Files.exists(entry.lexicalPath, LinkOption.NOFOLLOW_LINKS)) {
            // A broken entry must never cause us to delete a directory, an index, or an outside file.
            throw new StoreUpdateFailedException("Cannot delete the stored violation file for rule '" + description + "'");
        }

        Properties updated = copyOf(current.storedRules);
        updated.remove(description);
        try {
            writeProperties(current.index, updated);
        } catch (RuntimeException e) {
            throw e;
        }
        current.storedRules = updated;
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        StoreContext current = requireContext();
        String description = normalize(rule.getDescription());
        synchronized (current.lock) {
            current.storedRules = loadProperties(current.index);
            String fileName = current.storedRules.getProperty(description);
            checkArgument(fileName != null, "No rule stored with description '%s'", rule.getDescription());
            Path target = readableTarget(current, fileName);
            List<String> result = readLines(target);
            log.trace("Retrieved stored rule '{}' with {} violations: {}", description, result.size(), result);
            return result;
        }
    }

    private static StoreContext requireContext(StoreContext context) {
        if (context == null) {
            throw new IllegalStateException("Violation store has not been initialized");
        }
        return context;
    }

    private StoreContext requireContext() {
        return requireContext(context);
    }

    private static Path readableTarget(StoreContext current, String fileName) {
        try {
            Path lexical = current.folder.resolve(fileName).normalize();
            if (!isDirectPath(current.folder, lexical) || !Files.exists(lexical, LinkOption.NOFOLLOW_LINKS)) {
                throw new IOException("Stored violation file is not a regular file directly in the store folder");
            }
            Path target = lexical.toRealPath();
            if (!isDirectRegularTarget(current.folder, target) || target.equals(current.index)) {
                throw new IOException("Stored violation file is not a regular file directly in the store folder");
            }
            return target;
        } catch (IOException | InvalidPathExceptionWrapper e) {
            throw new StoreReadException(e);
        }
    }

    private Path writableTarget(StoreContext current, String fileName, String ownDescription, boolean newEntry) {
        try {
            Path lexical = current.folder.resolve(fileName).normalize();
            if (!isDirectPath(current.folder, lexical) || lexical.equals(current.index)) {
                throw new IOException("The violation file name must resolve to a direct child of the store folder");
            }
            if (newEntry) {
                if (current.storedRules.containsValue(fileName) || Files.exists(lexical, LinkOption.NOFOLLOW_LINKS)) {
                    throw new IOException("The violation file is already owned or exists");
                }
                return lexical;
            }
            if (!Files.exists(lexical, LinkOption.NOFOLLOW_LINKS)) {
                return lexical;
            }
            Path target = lexical.toRealPath();
            if (!isDirectRegularTarget(current.folder, target) || target.equals(current.index)) {
                throw new IOException("The violation file is not a regular file directly in the store folder");
            }
            return target;
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        } catch (InvalidPathExceptionWrapper e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private static boolean isDirectPath(Path folder, Path path) {
        return path.startsWith(folder) && folder.equals(path.getParent());
    }

    private static boolean isDirectRegularTarget(Path folder, Path target) {
        return target.startsWith(folder) && folder.equals(target.getParent()) && Files.isRegularFile(target);
    }

    private static boolean isRegularFile(Path path) {
        return Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS);
    }

    private static byte[] serialize(List<String> violations) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append('\n');
        }
        return builder.toString().getBytes(UTF_8);
    }

    private static String escape(String violation) {
        return violation.replace("\n", "\\\n");
    }

    private static String unescape(String violation) {
        return violation.replace("\\\n", "\n");
    }

    private static List<String> readLines(Path file) {
        try {
            String text = new String(Files.readAllBytes(file), UTF_8);
            if (text.isEmpty() || ONLY_LINE_BREAKS.matcher(text).matches()) {
                return Collections.emptyList();
            }
            List<String> result = new ArrayList<>();
            int start = 0;
            for (int i = 0; i < text.length(); i++) {
                if (text.charAt(i) == '\n' && (i == 0 || text.charAt(i - 1) != '\\')) {
                    if (i > start) {
                        result.add(unescape(text.substring(start, i)));
                    }
                    start = i + 1;
                }
            }
            if (start < text.length()) {
                result.add(unescape(text.substring(start)));
            }
            return result;
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
    }

    private static String normalize(String value) {
        return value.replace("\r\n", "\n");
    }

    private static Properties loadProperties(Path index) {
        Properties result = new Properties();
        try (InputStream input = Files.newInputStream(index)) {
            result.load(input);
            return result;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private static Properties copyOf(Properties source) {
        Properties result = new Properties();
        result.putAll(source);
        return result;
    }

    private static void writeProperties(Path index, Properties properties) {
        Path temporary = null;
        try {
            temporary = Files.createTempFile(index.getParent(), ".stored.rules-", ".tmp");
            try (OutputStream output = Files.newOutputStream(temporary)) {
                properties.store(output, "");
            }
            moveReplacing(temporary, index);
        } catch (IOException e) {
            if (temporary != null) {
                removeFileIfPresent(temporary);
            }
            throw new StoreUpdateFailedException(e);
        }
    }

    private static void writeNewFile(Path target, byte[] content) throws IOException {
        Path temporary = Files.createTempFile(target.getParent(), ".violation-", ".tmp");
        try {
            Files.write(temporary, content);
            moveReplacing(temporary, target);
        } finally {
            removeFileIfPresent(temporary);
        }
    }

    private static void moveReplacing(Path source, Path target) throws IOException {
        try {
            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (AtomicMoveNotSupportedException e) {
            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    private static void removeFileIfPresent(Path file) {
        try {
            Files.deleteIfExists(file);
        } catch (IOException ignored) {
            // Best effort cleanup of a temporary or newly-created file.
        }
    }

