    private static final class StoreConfiguration {
        private final boolean storeCreationAllowed;
        private final boolean storeUpdateAllowed;
        private final Integrity integrity;
        private final RuleViolationFileNameStrategy fileNameStrategy;
        private final boolean randomFileNames;

        private StoreConfiguration(boolean storeCreationAllowed, boolean storeUpdateAllowed, Integrity integrity,
                RuleViolationFileNameStrategy fileNameStrategy, boolean randomFileNames) {
            this.storeCreationAllowed = storeCreationAllowed;
            this.storeUpdateAllowed = storeUpdateAllowed;
            this.integrity = integrity;
            this.fileNameStrategy = fileNameStrategy;
            this.randomFileNames = randomFileNames;
        }

        private static StoreConfiguration from(Properties properties, boolean hasConstructorStrategy,
                RuleViolationFileNameStrategy constructorStrategy) {
            boolean creationAllowed = Boolean.parseBoolean(properties.getProperty(
                    ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
            boolean updateAllowed = Boolean.parseBoolean(properties.getProperty(
                    ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
            String integrityValue = properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT);
            Integrity integrity;
            try {
                integrity = Integrity.valueOf(integrityValue);
            } catch (IllegalArgumentException e) {
                throw new StoreInitializationFailedException(String.format(
                        "Invalid %s '%s'; accepted values are repair, fail and ignore",
                        INTEGRITY_PROPERTY_NAME, integrityValue));
            }
            if (integrity == Integrity.REPAIR && !updateAllowed) {
                throw new StoreInitializationFailedException(String.format(
                        "Integrity repair requires %s.%s=true",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
            }

            if (hasConstructorStrategy) {
                if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
                    throw new StoreInitializationFailedException(String.format(
                            "%s cannot be configured for a store constructed with a file name strategy",
                            FILE_NAMES_PROPERTY_NAME));
                }
                return new StoreConfiguration(creationAllowed, updateAllowed, integrity, constructorStrategy, false);
            }

            String fileNames = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT);
            RuleViolationFileNameStrategy strategy;
            boolean randomFileNames;
            if ("random".equals(fileNames)) {
                strategy = ignored -> UUID.randomUUID().toString();
                randomFileNames = true;
            } else if ("description".equals(fileNames)) {
                strategy = TextFileBasedViolationStore::descriptionFileName;
                randomFileNames = false;
            } else {
                strategy = instantiateStrategy(fileNames);
                randomFileNames = false;
            }
            return new StoreConfiguration(creationAllowed, updateAllowed, integrity, strategy, randomFileNames);
        }

        private static RuleViolationFileNameStrategy instantiateStrategy(String className) {
            try {
                Class<?> type = Class.forName(className);
                checkArgument(RuleViolationFileNameStrategy.class.isAssignableFrom(type),
                        "Configured file name strategy '%s' does not implement %s",
                        className, RuleViolationFileNameStrategy.class.getName());
                checkArgument(Modifier.isPublic(type.getModifiers()),
                        "Configured file name strategy '%s' must be public", className);
                Constructor<?> constructor = type.getConstructor();
                checkArgument(Modifier.isPublic(constructor.getModifiers()),
                        "Configured file name strategy '%s' must have a public no-argument constructor", className);
                return (RuleViolationFileNameStrategy) constructor.newInstance();
            } catch (StoreInitializationFailedException e) {
                throw e;
            } catch (Exception e) {
                throw new StoreInitializationFailedException(String.format(
                        "Could not instantiate file name strategy '%s' with a public no-argument constructor", className), e);
            }
        }
    }

