    private static String descriptionFileName(String description) {
        List<String> words = new ArrayList<>();
        Matcher matcher = DESCRIPTION_WORD.matcher(description);
        while (matcher.find()) {
            words.add(matcher.group());
        }
        String hash = shortHash(description);
        if (words.isEmpty()) {
            return "rule-" + hash;
        }
        String last = words.get(words.size() - 1);
        String result = last + "-" + hash;
        String first = words.get(0);
        if (!first.equals(last) && first.length() + 1 + result.length() <= 200) {
            result = first + "_" + result;
        }
        return result;
    }

    private static String shortHash(String description) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(description.getBytes(UTF_8));
            StringBuilder result = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                result.append(String.format("%02x", digest[i] & 0xff));
            }
            return result.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new AssertionError(e);
        }
    }

