+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        StoreContext current = requireContext();
+        String description = normalize(rule.getDescription());
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", description, violations.size(), violations);
+
+        synchronized (current.lock) {
+            if (!current.storeUpdateAllowed) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+            }
+
+            current.storedRules = loadProperties(current.index);
+            String recordedName = current.storedRules.getProperty(description);
+            if (violations.isEmpty() && recordedName == null) {
+                // In particular, do not ask a strategy for a name when there is nothing to store.
+                return;
+            }
+            if (violations.isEmpty()) {
+                forgetRule(current, description, recordedName);
+            } else {
+                storeViolations(current, description, recordedName, violations);
+            }
+        }
