+    private void storeViolations(StoreContext current, String description, String recordedName, List<String> violations) {
+        boolean newEntry = recordedName == null;
+        String fileName = newEntry ? createFileName(current.fileNameStrategy, description) : recordedName;
+        Path target = writableTarget(current, fileName, newEntry ? null : description, newEntry);
+        byte[] content = serialize(violations);
