+        boolean existed = Files.exists(target, LinkOption.NOFOLLOW_LINKS);
+        byte[] oldContent = null;
+        try {
+            if (existed) {
+                oldContent = Files.readAllBytes(target);
+                Files.write(target, content);
+            } else {
+                writeNewFile(target, content);
+            }
+
+            if (newEntry) {
+                Properties updated = copyOf(current.storedRules);
+                updated.setProperty(description, fileName);
+                try {
+                    writeProperties(current.index, updated);
+                } catch (RuntimeException e) {
+                    removeFileIfPresent(target);
+                    throw e;
+                }
+                current.storedRules = updated;
+            }
+        } catch (IOException e) {
+            if (existed && oldContent != null) {
+                try {
+                    Files.write(target, oldContent);
+                } catch (IOException ignored) {
