+
+    private static Path readableTarget(StoreContext current, String fileName) {
+        try {
+            Path lexical = current.folder.resolve(fileName).normalize();
+            if (!isDirectPath(current.folder, lexical) || !Files.exists(lexical, LinkOption.NOFOLLOW_LINKS)) {
+                throw new IOException("Stored violation file is not a regular file directly in the store folder");
+            }
+            Path target = lexical.toRealPath();
+            if (!isDirectRegularTarget(current.folder, target) || target.equals(current.index)) {
+                throw new IOException("Stored violation file is not a regular file directly in the store folder");
+            }
+            return target;
+        } catch (IOException | InvalidPathExceptionWrapper e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private Path writableTarget(StoreContext current, String fileName, String ownDescription, boolean newEntry) {
+        try {
+            Path lexical = current.folder.resolve(fileName).normalize();
+            if (!isDirectPath(current.folder, lexical) || lexical.equals(current.index)) {
+                throw new IOException("The violation file name must resolve to a direct child of the store folder");
+            }
+            if (newEntry) {
+                if (current.storedRules.containsValue(fileName) || Files.exists(lexical, LinkOption.NOFOLLOW_LINKS)) {
+                    throw new IOException("The violation file is already owned or exists");
+                }
+                return lexical;
+            }
+            if (!Files.exists(lexical, LinkOption.NOFOLLOW_LINKS)) {
+                return lexical;
+            }
+            Path target = lexical.toRealPath();
+            if (!isDirectRegularTarget(current.folder, target) || target.equals(current.index)) {
+                throw new IOException("The violation file is not a regular file directly in the store folder");
+            }
+            return target;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } catch (InvalidPathExceptionWrapper e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private static boolean isDirectPath(Path folder, Path path) {
+        return path.startsWith(folder) && folder.equals(path.getParent());
+    }
+
+    private static boolean isDirectRegularTarget(Path folder, Path target) {
+        return target.startsWith(folder) && folder.equals(target.getParent()) && Files.isRegularFile(target);
+    }
+
+    private static boolean isRegularFile(Path path) {
+        return Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private static byte[] serialize(List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append('\n');
+        }
+        return builder.toString().getBytes(UTF_8);
+    }
+
+    private static String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private static String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private static List<String> readLines(Path file) {
+        try {
+            String text = new String(Files.readAllBytes(file), UTF_8);
+            if (text.isEmpty() || ONLY_LINE_BREAKS.matcher(text).matches()) {
+                return Collections.emptyList();
+            }
+            List<String> result = new ArrayList<>();
+            int start = 0;
+            for (int i = 0; i < text.length(); i++) {
+                if (text.charAt(i) == '\n' && (i == 0 || text.charAt(i - 1) != '\\')) {
+                    if (i > start) {
+                        result.add(unescape(text.substring(start, i)));
+                    }
+                    start = i + 1;
+                }
+            }
+            if (start < text.length()) {
+                result.add(unescape(text.substring(start)));
+            }
+            return result;
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private static String normalize(String value) {
