+    }
+
+    private static void writeProperties(Path index, Properties properties) {
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(index.getParent(), ".stored.rules-", ".tmp");
+            try (OutputStream output = Files.newOutputStream(temporary)) {
+                properties.store(output, "");
+            }
+            moveReplacing(temporary, index);
+        } catch (IOException e) {
+            if (temporary != null) {
+                removeFileIfPresent(temporary);
+            }
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private static void writeNewFile(Path target, byte[] content) throws IOException {
+        Path temporary = Files.createTempFile(target.getParent(), ".violation-", ".tmp");
+        try {
+            Files.write(temporary, content);
+            moveReplacing(temporary, target);
