+    private static IntegrityReport inspect(Path folder, Path index, Properties storedRules,
+            RuleViolationFileNameStrategy strategy) {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : storedRules.stringPropertyNames()) {
+            String recordedName = storedRules.getProperty(description);
+            String derivedName = createFileNameForIntegrity(strategy, description);
+            entries.add(new Entry(description, recordedName, derivedName));
+        }
+        entries.sort(Comparator.comparing(entry -> entry.description));
+
+        Set<String> recordedNames = new HashSet<>();
+        for (Entry entry : entries) {
+            recordedNames.add(entry.recordedName);
+            resolveEntry(folder, index, entry);
+            resolveDerived(folder, entry);
+        }
+
+        for (int i = 0; i < entries.size(); i++) {
+            Entry first = entries.get(i);
+            for (int j = i + 1; j < entries.size(); j++) {
+                Entry second = entries.get(j);
+                if (first.recordedName.equals(second.recordedName)
+                        || (first.valid && second.valid && sameFile(first.target, second.target))) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
+        }
+
+        Map<String, Integer> derivedCounts = new HashMap<>();
+        for (Entry entry : entries) {
+            derivedCounts.put(entry.derivedName, derivedCounts.getOrDefault(entry.derivedName, 0) + 1);
+        }
+        for (Entry entry : entries) {
+            entry.misplaced = !entry.recordedName.equals(entry.derivedName);
+            entry.colliding = derivedCounts.get(entry.derivedName) > 1;
+            if (entry.misplaced) {
+                entry.occupied = entry.derivedPathInvalid
+                        || recordedByOther(entries, entry.derivedName, entry.description)
+                        || (entry.derivedPath != null && Files.exists(entry.derivedPath, LinkOption.NOFOLLOW_LINKS));
+            }
+            if (entry.valid) {
+                entry.resolved = readLines(entry.target).isEmpty();
+            }
+        }
+
+        List<String> unownedFiles = new ArrayList<>();
+        try (DirectoryStream<Path> children = Files.newDirectoryStream(folder)) {
+            for (Path child : children) {
+                if (!child.getFileName().toString().equals(STORED_RULES_FILE_NAME)
+                        && isRegularFile(child)
+                        && !recordedNames.contains(child.getFileName().toString())) {
+                    unownedFiles.add(child.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(unownedFiles);
+        return new IntegrityReport(entries, unownedFiles);
