+    private static boolean recordedByOther(List<Entry> entries, String name, String description) {
+        for (Entry other : entries) {
+            if (!other.description.equals(description) && name.equals(other.recordedName)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private static boolean sameFile(Path first, Path second) {
+        try {
+            return first.equals(second) || Files.isSameFile(first, second);
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private static void resolveEntry(Path folder, Path index, Entry entry) {
+        try {
+            entry.lexicalPath = folder.resolve(entry.recordedName).normalize();
+            if (!isDirectPath(folder, entry.lexicalPath)
+                    || !Files.exists(entry.lexicalPath, LinkOption.NOFOLLOW_LINKS)) {
+                entry.broken = true;
+                return;
+            }
+            entry.target = entry.lexicalPath.toRealPath();
+            entry.valid = isDirectRegularTarget(folder, entry.target) && !entry.target.equals(index);
+            entry.broken = !entry.valid;
+        } catch (IOException | RuntimeException e) {
+            entry.broken = true;
+        }
+    }
+
+    private static void resolveDerived(Path folder, Entry entry) {
+        try {
+            entry.derivedPath = folder.resolve(entry.derivedName).normalize();
+            entry.derivedPathInvalid = !isDirectPath(folder, entry.derivedPath);
+        } catch (RuntimeException e) {
+            entry.derivedPathInvalid = true;
+        }
+    }
+
+    private static String createFileNameForIntegrity(RuleViolationFileNameStrategy strategy, String description) {
+        try {
+            String result = strategy.createRuleFileName(description);
+            if (result == null || result.trim().isEmpty()) {
+                throw new StoreInitializationFailedException("The rule violation file name strategy returned no name");
+            }
+            return result;
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (RuntimeException e) {
+            throw new StoreInitializationFailedException("Could not derive a rule violation file name", e);
+        }
+    }
+
+    private static void repair(Path folder, Path index, Properties storedRules, IntegrityReport report) {
+        Properties updated = copyOf(storedRules);
+        boolean changed = false;
+
+        for (Entry entry : report.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                updated.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                try {
+                    Files.deleteIfExists(entry.target);
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException(e);
+                }
+                updated.remove(entry.description);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                try {
+                    Files.move(entry.target, entry.derivedPath);
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException(e);
+                }
+                updated.setProperty(entry.description, entry.derivedName);
+                changed = true;
+            }
+        }
+        if (changed) {
+            writeProperties(index, updated);
+            storedRules.clear();
+            storedRules.putAll(updated);
+        }
+    }
