+    private static final class StoreConfiguration {
+        private final boolean storeCreationAllowed;
+        private final boolean storeUpdateAllowed;
+        private final Integrity integrity;
+        private final RuleViolationFileNameStrategy fileNameStrategy;
+
+        private StoreConfiguration(boolean storeCreationAllowed, boolean storeUpdateAllowed, Integrity integrity,
+                RuleViolationFileNameStrategy fileNameStrategy) {
+            this.storeCreationAllowed = storeCreationAllowed;
+            this.storeUpdateAllowed = storeUpdateAllowed;
+            this.integrity = integrity;
+            this.fileNameStrategy = fileNameStrategy;
+        }
+
+        private static StoreConfiguration from(Properties properties, boolean hasConstructorStrategy,
+                RuleViolationFileNameStrategy constructorStrategy) {
